CREATE OR REPLACE FUNCTION public.supersede_waiting_flow_session(p_session_id uuid, p_event_id text, p_new_flow_id uuid, p_trigger_id text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE v_old public.flow_sessions%ROWTYPE; v_new_id uuid; BEGIN SELECT * INTO v_old FROM public.flow_sessions WHERE id = p_session_id AND status = 'active' AND waiting_for_input = true FOR UPDATE; IF NOT FOUND THEN RETURN NULL; END IF; IF EXISTS (SELECT 1 FROM public.flow_sessions WHERE consumed_event_id = p_event_id) THEN RETURN NULL; END IF; UPDATE public.flow_sessions SET status = 'cancelled', waiting_for_input = false, ended_reason = 'superseded_by_new_flow', consumed_event_id = p_event_id WHERE id = v_old.id; INSERT INTO public.flow_sessions(contact_id, flow_id, channel_id, status, variables, predecessor_session_id, consumed_event_id) VALUES (v_old.contact_id, p_new_flow_id, v_old.channel_id, 'active', jsonb_build_object('superseded_flow_id', v_old.flow_id::text, 'trigger_id', p_trigger_id), v_old.id, p_event_id || ':successor') RETURNING id INTO v_new_id; UPDATE public.flow_sessions SET successor_session_id = v_new_id WHERE id = v_old.id; RETURN v_new_id; END; $$;